/bin/bash -lc "python3 - <<'PY'
p='Task.v';s=open(p).read()
a=s.index('Lemma runtime_pure')
s=s[:a]+'''Lemma fp_split_letpair R L F A B :
  fp_split R L F -> fp_split L A B ->
  fp_split R (F ∪ A) B ∧ fp_split (F ∪ A) F A.
Proof. unfold fp_split. set_solver. Qed.

'''+s[a:]
s=s.replace('''        eapply RT_app with (R1:=F ∪ A) (R2:=B);
          [apply empty_env_split| | |exact Hv2];
        [clear - HR HL; unfold fp_split in *; set_solver|
          eapply RT_app; [apply empty_env_split| |exact Hf|exact Hv1];
          clear - HL; unfold fp_split in *; set_solver]''','''        let Hsplit := fresh in
        destruct (fp_split_letpair _ _ _ _ _ HR HL) as [Hsplit Hinner];
        eapply RT_app;
          [apply empty_env_split|exact Hsplit| |exact Hv2];
        eapply RT_app; [apply empty_env_split|exact Hinner|exact Hf|exact Hv1]''')
open(p,'w').write(s)
PY
timeout 45s rocq c -time -q -R theories diris -R .rocq-deps/stdpp stdpp Task.v > /tmp/session_time.log 2>&1"

